    def maxLength(self, arr: List[str]) -> int:
        ans = 0
        count = [0]*26
        counts = []
        new_arr = []

        for string in arr:
            flag = True
            tmp = [0]*26
            for ch in string:
                if tmp[ord(ch) - 97] == True:
                    flag = False
                    break
                else:
                    tmp[ord(ch) - 97] = True

            if flag == False:continue
            counts.append(tmp)
            new_arr.append(string)

        n = len(new_arr)

        def compatible(a,b):
            for i in range(26):
                if a[i] == True and b[i] == True: return False
            return True

        def addUp(a,b):
            for i in range(26):
                if b[i] == True: a[i] = True

        def solve(index,count):
            if index == n:return 0
            cpy = count.copy()
            ch1 = -inf
            if compatible(count,counts[index]):
                addUp(count,counts[index])
                ch1 = solve(index+1,count) + len(new_arr[index])
            ch2 = solve(index+1 , cpy)
            ans = max(ch1,ch2)
            return ans

        return solve(0,count)

class Solution:
    def getHappyString(self, n: int, k: int) -> str:
        ans = []
        letters = ['a','b','c']
        def happystr(n,prev,temp):
            if n==0:
                ans.append("".join(temp))
                return 
            for l in letters: 
                if l!=prev: 
                    happystr(n-1,l,temp+[l])
        happystr(n,"",[])
        if len(ans)<k:
            return ""
        return ans[k-1]

class Solution:
    def maxUniqueSplit(self, s: str) -> int:
        ans, n = 0, len(s)
        def dfs(i, cnt, visited):
            nonlocal ans, n
            if i == n: ans = max(ans, cnt); return  # stop condition
            for j in range(i+1, n+1):    
                if s[i:j] in visited: continue      # avoid re-visit/duplicates
                visited.add(s[i:j])                 # update visited set
                dfs(j, cnt+1, visited)              # backtracking
                visited.remove(s[i:j])              # recover visited set for next possibility
        dfs(0, 0, set())                            # function call
        return ans

