class Solution:
    def constructDistancedSequence(self, n: int) -> List[int]:
        def backtracking(n, i, result, lookup):
            if i == len(result):
                return True
            if result[i]:
                return backtracking(n, i+1, result, lookup)
            for x in reversed(range(1, n+1)):
                j = i if x == 1 else i+x
                if lookup[x] or j >= len(result) or result[j]:
                    continue
                result[i], result[j], lookup[x] = x, x, True
                if backtracking(n, i+1, result, lookup):
                    return True
                result[i], result[j], lookup[x] = 0, 0, False
            return False

        result, lookup = [0]*(2*n-1), [False]*(n+1)
        backtracking(n, 0, result, lookup)
        return result

class Solution:
    def splitString(self, s: str, last_val: int = None) -> bool:
        # Base case, remaining string is a valid solution
        if last_val and int(s) == last_val - 1:
            return True

        # Iterate through increasingly larger slices of s
        for i in range(1, len(s)):
            cur = int(s[:i])
            # If current slice is equal to last_val - 1, make
            # recursive call with remaining string and updated last_val
            if last_val is None or cur == last_val - 1:
                if self.splitString(s[i:], cur):
                    return True

        return False

